<template>
  <section class="decoration-page">
    <header class="decoration-head">
      <div><el-tag type="warning" effect="dark">可视化装修</el-tag><h2>页面装修</h2><p>租户配置覆盖平台默认素材位，发布后自动刷新小程序页面缓存。</p></div>
      <div><el-button :icon="Clock" @click="showVersions">版本记录</el-button><el-button :loading="saving" @click="saveDraft">保存草稿</el-button><el-button type="primary" :loading="publishing" @click="publish">发布页面</el-button></div>
    </header>
    <el-segmented v-model="pageCode" :options="pageOptions" @change="loadPage" />
    <div v-loading="loading" class="decoration-workspace">
      <aside class="module-tree">
        <strong>页面模块</strong><p>拖动素材位调整顺序</p>
        <section v-for="group in slotGroups" :key="group.moduleCode"><h4>{{ moduleLabel(group.moduleCode) }}</h4><button v-for="slot in group.items" :key="slot.slotKey" draggable="true" :class="{ active: selected?.slotKey === slot.slotKey, disabled: !slot.isEnabled }" @dragstart="dragKey = slot.slotKey" @dragover.prevent @drop="dropOn(slot.slotKey)" @click="selected = slot"><span>{{ slot.slotName }}</span><small>{{ slot.slotKey }}</small></button></section>
      </aside>
      <main class="phone-stage">
        <div class="phone-shell"><div class="phone-bar"><i></i><span>{{ pageLabel(pageCode) }}</span><b>•••</b></div><div class="phone-content">
          <article v-for="slot in slots" :key="slot.slotKey" :class="['phone-slot', { selected: selected?.slotKey === slot.slotKey, disabled: !slot.isEnabled }]" @click="selected = slot">
            <img v-if="slot.materialUrl || slot.fallbackUrl" :src="slot.materialUrl || slot.fallbackUrl" :alt="slot.altText || slot.slotName" @error="useFallback($event, slot)" />
            <div v-else><span>图片素材位</span><small>{{ slot.slotKey }}</small></div><em>{{ slot.slotName }}</em>
          </article>
          <el-empty v-if="!slots.length" description="当前页面暂无素材位" :image-size="64" />
        </div><div class="phone-tabs"><span v-for="item in pageOptions" :key="item.value" :class="{ active: item.value === pageCode }">{{ item.label }}</span></div></div>
      </main>
      <aside class="property-panel">
        <template v-if="selected">
          <header><div><strong>{{ selected.slotName }}</strong><small>{{ selected.slotKey }}</small></div><el-switch v-model="selected.isEnabled" @change="saveSelectedSlot" /></header>
          <label>素材</label><button class="selected-material" @click="pickerOpen = true"><img v-if="selected.materialUrl" :src="selected.materialUrl" :alt="selected.altText" /><span v-else>点击选择素材</span></button>
          <el-button type="primary" plain @click="pickerOpen = true">从素材中心选择</el-button>
          <label>替代文本</label><el-input v-model="selected.altText" maxlength="120" show-word-limit />
          <label>模块</label><el-input v-model="selected.moduleCode" />
          <label>排序</label><el-input-number v-model="selected.sortOrder" :min="0" :step="10" />
          <label>生效时间</label><el-date-picker v-model="selected.effectiveStartTime" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" placeholder="立即生效" />
          <label>失效时间</label><el-date-picker v-model="selected.effectiveEndTime" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" placeholder="长期有效" />
          <el-button :loading="savingSlot" @click="saveSelectedSlot">保存素材位</el-button>
        </template><el-empty v-else description="选择左侧素材位进行配置" :image-size="72" />
      </aside>
    </div>

    <el-dialog v-model="pickerOpen" title="选择素材" width="min(920px, 94vw)"><div class="picker-toolbar"><el-input v-model="assetQuery" clearable placeholder="搜索素材" @keyup.enter="loadAssets" /><el-select v-model="assetCategory" clearable placeholder="全部分类" @change="loadAssets"><el-option v-for="item in categories" :key="item.id" :label="item.name" :value="item.id" /></el-select><el-button :icon="Refresh" @click="loadAssets">刷新</el-button></div><div class="picker-grid"><button v-for="asset in assets" :key="asset.id" :class="{ active: selected?.assetId === asset.id }" @click="chooseAsset(asset)"><img :src="asset.thumbnailUrl || asset.cdnUrl || asset.originalUrl" :alt="asset.name" /><strong>{{ asset.name }}</strong><small>{{ asset.width }}×{{ asset.height }}</small></button></div><el-empty v-if="!assets.length" description="暂无可用素材" /></el-dialog>
    <el-drawer v-model="versionsOpen" title="发布版本" size="440px"><el-timeline><el-timeline-item v-for="version in versions" :key="version.id" :timestamp="version.createdAt"><div class="version-card"><strong>版本 {{ version.version }}</strong><p>{{ version.changeNote || '页面发布' }}</p><el-button size="small" @click="rollback(version.version)">回滚到此版本</el-button></div></el-timeline-item></el-timeline><el-empty v-if="!versions.length" description="尚未发布版本" /></el-drawer>
  </section>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { ElMessage, ElMessageBox } from "element-plus";
import { Clock, Refresh } from "@element-plus/icons-vue";
import { getPageConfig, listMediaAssets, listMediaCategories, listPageConfigVersions, publishPageConfig, rollbackPageConfig, savePageConfig, updatePageSlot, type MediaAsset, type MediaCategory, type PageAssetSlot, type PageConfig, type PageConfigVersion } from "../../api/media";
const props=withDefaults(defineProps<{initialPageCode?:string}>(),{initialPageCode:"home"});
queueMicrotask(()=>{pageCode.value=props.initialPageCode});
const pageOptions=[{label:"首页",value:"home"},{label:"创作",value:"studio"},{label:"作品",value:"assets"},{label:"我的",value:"profile"}];const pageCode=ref("home");const config=ref<PageConfig>();const slots=ref<PageAssetSlot[]>([]);const selected=ref<PageAssetSlot>();const loading=ref(false);const saving=ref(false);const publishing=ref(false);const savingSlot=ref(false);const pickerOpen=ref(false);const versionsOpen=ref(false);const versions=ref<PageConfigVersion[]>([]);const assets=ref<MediaAsset[]>([]);const categories=ref<MediaCategory[]>([]);const assetQuery=ref("");const assetCategory=ref("");const dragKey=ref("");
const slotGroups=computed(()=>{const groups=new Map<string,PageAssetSlot[]>();slots.value.forEach(slot=>groups.set(slot.moduleCode,[...(groups.get(slot.moduleCode)||[]),slot]));return Array.from(groups.entries()).map(([moduleCode,items])=>({moduleCode,items}))});
async function loadPage(){loading.value=true;selected.value=undefined;try{const response=await getPageConfig(pageCode.value);config.value=response.item;slots.value=[...response.slots].sort((a,b)=>a.sortOrder-b.sortOrder)}catch(error){ElMessage.error(error instanceof Error?error.message:"页面配置加载失败")}finally{loading.value=false}}
async function loadAssets(){const response=await listMediaAssets({page:1,pageSize:60,q:assetQuery.value,categoryId:assetCategory.value,status:"ACTIVE"});assets.value=response.items}
async function chooseAsset(asset:MediaAsset){if(!selected.value)return;selected.value.assetId=asset.id;selected.value.materialUrl=asset.cdnUrl||asset.originalUrl;await saveSelectedSlot();pickerOpen.value=false}
async function saveSelectedSlot(){if(!selected.value)return;savingSlot.value=true;try{const response=await updatePageSlot(pageCode.value,selected.value.slotKey,{assetId:selected.value.assetId||"",fallbackAssetId:selected.value.fallbackAssetId||"",altText:selected.value.altText||"",moduleCode:selected.value.moduleCode,slotName:selected.value.slotName,sortOrder:selected.value.sortOrder,isEnabled:selected.value.isEnabled,effectiveStartTime:selected.value.effectiveStartTime||"",effectiveEndTime:selected.value.effectiveEndTime||"",extraConfig:selected.value.extraConfig||{}});const index=slots.value.findIndex(item=>item.slotKey===response.item.slotKey);if(index>=0)slots.value[index]=response.item;selected.value=response.item;ElMessage.success("素材位已保存")}catch(error){ElMessage.error(error instanceof Error?error.message:"素材位保存失败")}finally{savingSlot.value=false}}
async function saveDraft(){saving.value=true;try{const modules=slotGroups.value.map(group=>({moduleCode:group.moduleCode,enabled:group.items.some(item=>item.isEnabled),slots:group.items.map(item=>item.slotKey)}));const response=await savePageConfig(pageCode.value,{...(config.value?.config||{}),modules});config.value=response.item;ElMessage.success("草稿已保存")}catch(error){ElMessage.error(error instanceof Error?error.message:"草稿保存失败")}finally{saving.value=false}}
async function publish(){try{const {value}=await ElMessageBox.prompt("填写本次发布说明","发布页面配置",{inputPlaceholder:"例如：更换首页夏季活动素材"});publishing.value=true;await saveDraft();const response=await publishPageConfig(pageCode.value,value);config.value=response.item;ElMessage.success(`版本 ${response.item.version} 已发布`)}catch(error){if(error!=="cancel"&&error!=="close")ElMessage.error(error instanceof Error?error.message:"发布失败")}finally{publishing.value=false}}
async function showVersions(){const response=await listPageConfigVersions(pageCode.value);versions.value=response.items;versionsOpen.value=true}
async function rollback(version:number){try{await ElMessageBox.confirm(`回滚到版本 ${version} 并立即发布？`,`版本回滚`,{type:"warning"});await rollbackPageConfig(pageCode.value,version);versionsOpen.value=false;await loadPage();ElMessage.success("页面已回滚并发布")}catch(error){if(error!=="cancel"&&error!=="close")ElMessage.error(error instanceof Error?error.message:"回滚失败")}}
async function dropOn(targetKey:string){const sourceIndex=slots.value.findIndex(item=>item.slotKey===dragKey.value);const targetIndex=slots.value.findIndex(item=>item.slotKey===targetKey);if(sourceIndex<0||targetIndex<0||sourceIndex===targetIndex)return;const [moved]=slots.value.splice(sourceIndex,1);slots.value.splice(targetIndex,0,moved);slots.value.forEach((item,index)=>item.sortOrder=(index+1)*10);selected.value=moved;await saveSelectedSlot()}
function useFallback(event:Event,slot:PageAssetSlot){const image=event.target as HTMLImageElement;if(slot.fallbackUrl&&image.src!==slot.fallbackUrl)image.src=slot.fallbackUrl;else image.style.display="none"}
function pageLabel(code:string){return pageOptions.find(item=>item.value===code)?.label||code}function moduleLabel(code:string){return ({hero:"主视觉",quick:"快捷入口",capability:"AI 能力",employee:"AI 员工",inspiration:"灵感推荐",banner:"Banner",template:"创作模板",default:"默认封面",header:"头部",member:"会员区"} as Record<string,string>)[code]||code}
onMounted(async()=>{const categoryResponse=await listMediaCategories();categories.value=categoryResponse.items;await Promise.all([loadPage(),loadAssets()])});
</script>

<style scoped>
.decoration-page{display:grid;gap:18px}.decoration-head{display:flex;align-items:flex-start;justify-content:space-between;padding:24px;border:1px solid #e7e9f2;border-radius:18px;background:linear-gradient(135deg,#fff,#fff8eb)}.decoration-head h2{margin:10px 0 6px;font-size:26px}.decoration-head p{margin:0;color:#667085}.decoration-head>div:last-child{display:flex;gap:10px}.decoration-workspace{display:grid;grid-template-columns:250px minmax(360px,1fr) 300px;min-height:680px;border:1px solid #e7e9f2;border-radius:18px;background:#fff;overflow:hidden}.module-tree,.property-panel{padding:18px;background:#fafbfe}.module-tree{border-right:1px solid #eaecf0}.module-tree>p{margin:5px 0 18px;color:#98a2b3;font-size:12px}.module-tree section{display:grid;gap:6px;margin-bottom:16px}.module-tree h4{margin:0 0 3px;color:#344054}.module-tree button{display:grid;gap:3px;border:1px solid transparent;border-radius:9px;padding:9px;background:#fff;text-align:left;cursor:grab}.module-tree button small{overflow:hidden;color:#98a2b3;text-overflow:ellipsis}.module-tree button.active{border-color:#7c6ee6;background:#f0eeff}.module-tree button.disabled{opacity:.5}.phone-stage{display:grid;place-items:center;padding:28px;background:radial-gradient(circle at 50% 15%,#f0edff,#f7f8fc 45%,#eef1f6)}.phone-shell{display:grid;width:330px;height:620px;grid-template-rows:42px 1fr 52px;border:9px solid #1b1c22;border-radius:36px;background:#f8f8fb;box-shadow:0 24px 70px #10182836;overflow:hidden}.phone-bar,.phone-tabs{display:flex;align-items:center;justify-content:space-around;background:#fff}.phone-bar i{width:58px;height:16px;border-radius:10px;background:#1b1c22}.phone-bar span{font-weight:800}.phone-bar b{letter-spacing:2px}.phone-content{display:grid;gap:10px;align-content:start;padding:13px;overflow:auto}.phone-slot{position:relative;min-height:88px;border:2px solid transparent;border-radius:14px;background:#fff;overflow:hidden;cursor:pointer}.phone-slot img{width:100%;height:112px;object-fit:cover}.phone-slot>div{display:grid;height:90px;place-content:center;text-align:center;color:#98a2b3}.phone-slot>div small{font-size:9px}.phone-slot em{position:absolute;bottom:7px;left:8px;border-radius:6px;padding:3px 6px;background:#101828b8;color:#fff;font-size:10px;font-style:normal}.phone-slot.selected{border-color:#7c6ee6}.phone-slot.disabled{filter:grayscale(1);opacity:.45}.phone-tabs{font-size:11px;color:#98a2b3}.phone-tabs .active{color:#6941c6;font-weight:800}.property-panel{display:flex;flex-direction:column;gap:10px;border-left:1px solid #eaecf0}.property-panel header{display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:8px}.property-panel header div{display:grid;gap:4px}.property-panel header small{color:#98a2b3}.property-panel label{margin-top:6px;color:#667085;font-size:12px}.selected-material{height:146px;border:1px dashed #c9ceda;border-radius:12px;background:#fff;overflow:hidden;cursor:pointer}.selected-material img{width:100%;height:100%;object-fit:cover}.selected-material span{color:#98a2b3}.picker-toolbar{display:grid;grid-template-columns:1fr 190px auto;gap:10px;margin-bottom:16px}.picker-grid{display:grid;max-height:520px;grid-template-columns:repeat(4,1fr);gap:12px;overflow:auto}.picker-grid button{display:grid;gap:6px;border:2px solid transparent;border-radius:12px;padding:7px;background:#f7f8fa;text-align:left;cursor:pointer}.picker-grid button.active{border-color:#7c6ee6}.picker-grid img{width:100%;height:110px;border-radius:8px;object-fit:cover}.picker-grid small{color:#98a2b3}.version-card p{margin:6px 0;color:#667085}@media(max-width:1100px){.decoration-workspace{grid-template-columns:210px 1fr}.property-panel{grid-column:1/-1;border-top:1px solid #eaecf0;border-left:0}.decoration-head{gap:16px;flex-direction:column}}@media(max-width:760px){.decoration-workspace{grid-template-columns:1fr}.module-tree{border-right:0;border-bottom:1px solid #eaecf0}.picker-grid{grid-template-columns:repeat(2,1fr)}}
</style>
